import 'package:flutter/widgets.dart';

/// One mode of a colour scheme, in the web app's terms.
class SchemePalette {
  const SchemePalette({
    required this.background,
    required this.card,
    required this.sidebar,
    required this.muted,
    required this.foreground,
    required this.mutedForeground,
    required this.accent,
    required this.accentStrong,
    required this.accentInk,
    required this.border,
    required this.divider,
    required this.input,
    required this.destructive,
  });

  final Color background;
  final Color card;
  final Color sidebar;
  final Color muted;
  final Color foreground;
  final Color mutedForeground;
  final Color accent;
  final Color accentStrong;
  final Color accentInk;
  final Color border;
  final Color divider;
  final Color input;
  final Color destructive;
}

/// A colour scheme offered in Settings, with its light and dark palettes.
class AppScheme {
  const AppScheme({
    required this.id,
    required this.name,
    required this.light,
    required this.dark,
  });

  final String id;
  final String name;
  final SchemePalette light;
  final SchemePalette dark;

  SchemePalette of(Brightness brightness) =>
      brightness == Brightness.dark ? dark : light;
}

